import * as THREE from './vendor/three.module.js';
const stage=document.querySelector('#book-stage'),prev=document.querySelector('#book-prev'),next=document.querySelector('#book-next'),count=document.querySelector('#book-count'),desc=document.querySelector('#book-description'),fallbackTitle=document.querySelector('#fallback-title'),fallbackItems=document.querySelector('#fallback-items');
const pages=[{title:'Biryani',items:['Mutton Biryani','Chicken Biryani','Mutton Special Biryani','Chicken Special Biryani']},{title:'Kebabs',items:['Chicken Tikka Kabab','Chicken Reshmi Kabab','Masala Tikka','Chicken Kebab Platter']},{title:'Main course',items:['Chicken Methi Malai','Chicken Manchurian','Chicken in Mustard Coriander Sauce','Mutton Tikia']},{title:'To finish',items:['Firni','Breads & accompaniments','Explore the full menu','Ask us about catering']}];
let current=0,turning=false,renderer,scene,camera,turnMesh,staticRight,staticLeft,book,frame=0,start=0,direction=1;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
function updateText(){let p=pages[current];count.textContent=`0${current+1} / 04`;prev.disabled=current===0;next.disabled=current===pages.length-1;desc.textContent=`Page ${current+1}: ${p.title}. ${p.items.join(', ')}`;fallbackTitle.textContent=p.title;fallbackItems.replaceChildren(...p.items.map(t=>{let li=document.createElement('li');li.textContent=t;return li}))}updateText();
function canvasTexture(p,left=false){const c=document.createElement('canvas');c.width=768;c.height=1100;let x=c.getContext('2d');x.fillStyle=left?'#5a1719':'#f3e4c8';x.fillRect(0,0,768,1100);let g=x.createLinearGradient(0,0,768,0);g.addColorStop(0,'rgba(75,31,20,.18)');g.addColorStop(.12,'rgba(255,255,255,.03)');g.addColorStop(1,'rgba(62,31,12,.08)');x.fillStyle=g;x.fillRect(0,0,768,1100);x.strokeStyle=left?'#d7aa68':'#b78a52';x.lineWidth=4;x.strokeRect(30,30,708,1040);x.lineWidth=1.5;x.strokeRect(43,43,682,1014);x.textAlign='center';x.fillStyle=left?'#e9c787':'#7a3e27';x.font='26px Georgia';x.fillText('✧  SUFI PALACE  ✧',384,105);x.strokeStyle=left?'#c99e62':'#b78a52';x.beginPath();x.moveTo(95,136);x.lineTo(673,136);x.stroke();if(left){x.strokeStyle='#dfb878';x.lineWidth=3;x.beginPath();x.moveTo(110,890);x.lineTo(110,430);x.bezierCurveTo(110,330,205,280,260,250);x.bezierCurveTo(300,225,350,195,384,160);x.bezierCurveTo(418,195,468,225,508,250);x.bezierCurveTo(563,280,658,330,658,430);x.lineTo(658,890);x.stroke();x.font='italic 66px Georgia';x.fillText('Sufi Palace',384,520);x.font='26px Georgia';x.fillText('COLLEGE STREET, KOLKATA',384,595);x.font='80px Georgia';x.fillText('✥',384,745)}else{x.fillStyle='#5b241d';x.font='78px Georgia';x.fillText(p.title,384,245);x.font='24px Georgia';x.fillStyle='#ab754c';x.fillText('✥',384,295);p.items.forEach((item,i)=>{let y=390+i*125;x.fillStyle='#603123';x.font='36px Georgia';x.fillText(item,384,y);x.strokeStyle='#caa77b';x.lineWidth=1;x.beginPath();x.moveTo(145,y+30);x.lineTo(623,y+30);x.stroke()});x.fillStyle='#946b4f';x.font='23px Georgia';x.fillText('Please ask us for today’s menu',384,970);x.fillText('and availability',384,1006)}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=4;return t}
function setTex(mesh,tex){let old=mesh.material.map;mesh.material.map=tex;mesh.material.needsUpdate=true;if(old)old.dispose()}
function init3D(){try{renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.setClearColor(0x000000,0);stage.appendChild(renderer.domElement);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(34,1,.1,100);camera.position.set(0,0.8,7.0);camera.lookAt(0,0,0);scene.add(new THREE.AmbientLight(0xffffff,1.6));let light=new THREE.DirectionalLight(0xffd89d,2.5);light.position.set(-3,5,7);scene.add(light);book=new THREE.Group();book.rotation.x=-.12;book.rotation.z=-.015;scene.add(book);let cover=new THREE.Mesh(new THREE.BoxGeometry(4.7,3.2,.13),new THREE.MeshStandardMaterial({color:0x481014,roughness:.55}));cover.position.z=-.1;book.add(cover);let goldEdge=new THREE.Mesh(new THREE.BoxGeometry(4.62,3.12,.05),new THREE.MeshStandardMaterial({color:0xc79851,metalness:.55,roughness:.45}));goldEdge.position.z=-.02;book.add(goldEdge);const geo=new THREE.PlaneGeometry(2.2,3,32,8);const mat=tex=>new THREE.MeshStandardMaterial({map:tex,roughness:.9,side:THREE.DoubleSide});staticLeft=new THREE.Mesh(geo,mat(canvasTexture(pages[0],true)));staticLeft.position.set(-1.1,0,.025);book.add(staticLeft);staticRight=new THREE.Mesh(geo,mat(canvasTexture(pages[0])));staticRight.position.set(1.1,0,.03);book.add(staticRight);let spine=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,3.1,12),new THREE.MeshStandardMaterial({color:0x4a2118}));spine.position.z=.06;book.add(spine);let pivot=new THREE.Group();pivot.position.set(0,0,.07);book.add(pivot);let turnGeo=new THREE.PlaneGeometry(2.2,3,40,10);turnGeo.translate(1.1,0,0);turnMesh=new THREE.Mesh(turnGeo,mat(canvasTexture(pages[0])));pivot.add(turnMesh);turnMesh.userData.pivot=pivot;turnMesh.visible=false;stage.classList.add('ready');function resize(){let w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.position.z=w/h<1.3?10.0:7.0;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(stage);resize();renderer.render(scene,camera)}catch(e){if(renderer?.domElement)renderer.domElement.remove();renderer=null;stage.classList.remove('ready')}}
function redraw(){if(!renderer)return;setTex(staticRight,canvasTexture(pages[current]));setTex(staticLeft,canvasTexture(pages[Math.max(0,current-1)],current===0));renderer.render(scene,camera)}
function turn(dir){let target=current+dir;if(turning||target<0||target>=pages.length)return;if(!renderer||reduce){current=target;updateText();redraw();return}turning=true;direction=dir;turnMesh.visible=true;setTex(turnMesh,canvasTexture(pages[dir>0?current:target]));if(dir<0)setTex(staticLeft,canvasTexture(pages[Math.max(0,target-1)],target===0));else setTex(staticRight,canvasTexture(pages[target]));start=performance.now();cancelAnimationFrame(frame);frame=requestAnimationFrame(animate)}
function animate(now){let t=Math.min(1,(now-start)/1100),ease=t*t*(3-2*t),angle=direction>0?-Math.PI*ease:-Math.PI*(1-ease);turnMesh.userData.pivot.rotation.y=angle;const pos=turnMesh.geometry.attributes.position;for(let i=0;i<pos.count;i++){let x=pos.getX(i);pos.setZ(i,Math.sin(Math.PI*x/2.2)*Math.sin(Math.PI*t)*.3)}pos.needsUpdate=true;turnMesh.geometry.computeVertexNormals();renderer.render(scene,camera);if(t<1){frame=requestAnimationFrame(animate)}else{current+=direction;turnMesh.visible=false;turning=false;updateText();redraw()}}
prev.addEventListener('click',()=>turn(-1));next.addEventListener('click',()=>turn(1));let pointerX=null;stage.addEventListener('pointerdown',e=>{pointerX=e.clientX});stage.addEventListener('pointerup',e=>{if(pointerX===null)return;let d=e.clientX-pointerX;pointerX=null;if(Math.abs(d)>45)turn(d<0?1:-1)});stage.addEventListener('pointercancel',()=>pointerX=null);init3D();
